const base = Date.UTC(2026, 0, 1)

const BASE_VOCABULARY: Word[] = (Object.keys(LEVELS) as Cefr[]).flatMap((cefr, li) =>
  LEVELS[cefr].map((r, i) => ({
    id: `seed-${r.w.replace(/\s+/g, '-')}`,
    word: r.w,
    ipa: { uk: `/${r.uk}/`, us: `/${r.us ?? r.uk}/` },
    pos: r.pos,
    meaningVi: r.vi,
    definitionEn: r.def,
    examples: r.ex.map(([en, vi]) => ({ en, vi })),
    synonyms: r.syn ?? [],
    antonyms: r.ant ?? [],
    collocations: r.col ?? [],
    phrasalVerbs: r.pv ?? [],
    wordFamily: r.fam ?? [],
    cefr,
    topics: r.t,
    source: { cefr: 'suggested' as const, cefrRef: SEED_REF, content: 'curated' as const, note: r.note },
    createdAt: new Date(base + (li * 20 + i) * 60000).toISOString(),
  })),
)

/** Gói từ vựng công sở/TOEIC nối thêm vào kho gốc (bỏ qua từ đã có sẵn để không trùng). */
const have = new Set(BASE_VOCABULARY.map((w) => w.word.toLowerCase()))
const PACK: Word[] = TOEIC_PACK.filter((r) => !have.has(r.w.toLowerCase())).map((r, i) => ({
  id: `seed-${r.w.replace(/\s+/g, '-')}`,
  word: r.w,
  ipa: { uk: `/${r.uk}/`, us: `/${r.uk}/` },
  pos: r.pos,
  meaningVi: r.vi,
  definitionEn: r.def,
  examples: [{ en: r.ex[0], vi: r.ex[1] }],
  synonyms: r.syn ?? [],
  antonyms: r.ant ?? [],
  collocations: r.col ?? [],
  phrasalVerbs: [],
  wordFamily: r.fam ?? [],
  cefr: r.cefr,
  topics: r.t,
  source: { cefr: 'suggested' as const, cefrRef: SEED_REF, content: 'curated' as const },
  createdAt: new Date(base + (900 + i) * 60000).toISOString(),
}))

export const SEED_VOCABULARY: Word[] = [...BASE_VOCABULARY, ...PACK]
